    static int ବଣ୍ଟନ_ଷ୍ଟୋରେଜ୍(int 종류, int ଦୈର୍ଘ୍ୟ_ମୂଲ୍ୟ) { return 새기억(종류, ଦୈର୍ଘ୍ୟ_ମୂଲ୍ୟ); }
